        } else
            SetState((ETavernGameStates)2);
        break;
    }
    case 10:
        SetStateAfterOK(GetTextWithNarrator(GamePlayed ? def->FarewellSubsequent : def->FarewellInitial), GetText(def->FarewellForward),
