    long minY = GFFloatToLongFloor((sphere.Center.Y - sphere.Radius - LookupGridWorldY) * 0.0625);
    long maxX = GFFloatToLongFloor((sphere.Radius + sphere.Center.X - LookupGridWorldX) * 0.0625);
